/* @lc app=leetcode id=4032 lang=kotlin */ class Solution { fun longestSubarray(nums: IntArray, k: Int): Int = IntArray(100_001) { it }.also { sp -> (2..316).forEach { i -> if (sp[i] == i) (i * i..100_000 step i).forEach { if (sp[it] == it) sp[it] = i } } }.let { sp -> nums.map { x -> generateSequence(x) { r -> (r / sp[r]).takeIf { it > 1 } }.map { sp[it] }.distinct().toList() }.let { fs -> HashMap<Int, Int>().let { cnt -> fs.indices.fold(0 to 0) { (left, best), r -> fs[r].forEach { cnt.merge(it, 1) { a, b -> a + b } }.let { generateSequence(left) { l -> if (cnt.size > k) fs[l].forEach { p -> cnt.merge(p, -1) { a, b -> a + b }.also { v -> if (v == 0) cnt.remove(p) } }.let { l + 1 } else null }.last().let { nl -> nl to maxOf(best, r - nl + 1) } } }.second } } } }